// A module's k6 scripts, generated from its verified workload (G7, criterion 4; docs/conventions.md "Script-built
// agents", D-049 variant A: the script writes the code, the k6-script-writer fills only slots).
//
//   k6-tests/<p>/scripts/<m>-<name>.js        one per workload.json scenario: fully managed ("Generated by
//                                             scripts/k6-code.mjs — do not edit"), re-rendered by build, drift-checked
//                                             by check. Header (id, type, kind, endpoints, citation or rationale), the
//                                             G4 lib imports, `options` = the scenario's workload.json options verbatim,
//                                             setup() (assertAllowedHost, requireFullRun(<mutates>), the data slot), the
//                                             generated requests (method, url(<path relative to the k6 overlay's
//                                             basePath, which url() prepends>), the endpoint tag, checkStatus
//                                             against the plan's expected status), a weighted pick for a mix, the
//                                             create -> (return unless the expected create status) -> trackLeftover
//                                             (untrackedCreate when a 2xx create has no id) -> steps bound only to the
//                                             flow's creates (child creates tracked the same way) -> deletes, children
//                                             first -> trackDeleted (on a 2xx) chain for a flow, the cited
//                                             think time, teardown() and handleSummary.
//   k6-tests/<p>/scripts/slots/<m>.js         the agent's only file: a generated skeleton around marked slots
//                                             ("// k6-code:begin <key>" ... "// k6-code:end <key>"); build keeps every
//                                             body. In scripts/slots/ so no module's "<m>-*.js" glob ever matches it.
//   artifacts/<p>/modules/<m>/k6/code-plan.json  the model (schema k6-code-plan): scripts, requests, slots (needed,
//                                             filled); `verified` stamped by a passing check
//   artifacts/<p>/modules/<m>/k6/parked.json  bodies whose slot is no longer generated (schema k6-code-parked); they
//                                             come back with their slot
//
// Slots (keys; the function each one is):
//   data              setupData()               the setup data, returned by setup(), passed to every slot as `data`
//   path:<EP>         path_<EP>(data, ref)      the values of a read's path parameters (a write's come only from a
//                                               flow's creates: never a path slot, D-005)
//   query:<EP>        query_<EP>(data, ref)     the query parameters (only for an endpoint with query parameters)
//   body:<EP>         body_<EP>(data, ref)      the JSON body (POST, PUT, PATCH, GraphQL)
//   checks:<EP>       checks_<EP>(res, data)    extra checks on the response, through lib/checks.js only
// `ref` is the flow's created entity (undefined outside a flow and in the create's own body).
//
// Slot bodies are scanned by construction (agent-scope.mjs): every free identifier is a parameter, an imported
// helper of the slot's kind or a pure global used as a call; no property walk to a constructor; no computed access; no
// escape that can spell a name; plus the k6 rules below (no request API, import, environment, sleep, eval; no URL or
// secret-shaped literal; no change to an object the slot did not create).
//
// setup() creates nothing (slots send no request), so teardown() has nothing to delete: an entity is created per
// iteration, recorded with trackLeftover at once, and deleted by the flow's last step (k6 VUs share no iteration state);
// a 2xx delete calls trackDeleted, so lib/summary.js leaves it out of <script>.created.json.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import path from "node:path";
import { freeIdentifierFindings, parseAgentCode, propertyFindings, walk as astWalk } from "./agent-scope.mjs";
import { builtinPatchFindings } from "./api-code.mjs";
import { readJson, writeJson } from "./endpoints.mjs";
import { looksLikeSecret, URL_RE } from "./foundation.mjs";
import { walk } from "./gate/common.mjs";
import { scanTs } from "./ts-scan.mjs";
import { stampVerified, unverifiedReason } from "./verified.mjs";
import { bindsOf, createIdPointer, flowDeletes, flowProblems, isCreate, pathParamsOf, rootDeleteStep, workloadPaths, workloadUnverified } from "./workload.mjs";

export const HEADER = "Generated by scripts/k6-code.mjs — do not edit.";
export const SLOT_HEADER = "Generated by scripts/k6-code.mjs around the k6-script-writer's slots";
export const SLOT_KINDS = ["data", "path", "query", "body", "checks"];
// What a slot body may name besides its parameters and the pure globals (agent-scope.mjs PURE_GLOBALS).
export const SLOT_HELPERS = { value: ["uniqueName", "uniqueEmail", "pick"], checks: ["checkStatus", "checkJsonKeys", "checkLatency"] };
export const SLOT_PARAMS = { data: [], path: ["data", "ref"], query: ["data", "ref"], body: ["data", "ref"], checks: ["res", "data"] };
// Names a slot never uses, in any position but after a dot: the request API, the module system, the environment and
// the runtime's escape hatches. Also .call/.apply/.bind as members.
export const SLOT_FORBIDDEN = ["http", "ws", "grpc", "fetch", "XMLHttpRequest", "import", "export", "require", "open", "__ENV", "__VU", "__ITER", "sleep", "globalThis", "global", "eval", "Function", "Reflect", "Proxy", "check", "group", "fail", "exec", "execution", "crypto", "encoding"];
const BAD_MEMBERS = ["call", "apply", "bind"];
const BODY_METHODS = ["POST", "PUT", "PATCH"];

const nl = (t) => String(t ?? "").replace(/\r\n?/g, "\n");
const one = (t) => String(t ?? "").replace(/\s+/g, " ").trim();
const safe = (id) => String(id).replace(/[^A-Za-z0-9_$]/g, "_");
const q1 = (s) => `'${String(s).replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
const isIdent = (s) => /^[A-Za-z_$][\w$]*$/.test(s);
const member = (obj, name) => (isIdent(name) ? `${obj}.${name}` : `${obj}[${q1(name)}]`);
const canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === "object" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);
const same = (a, b) => JSON.stringify(canon(a)) === JSON.stringify(canon(b));
const rel = (root, f) => path.relative(root, f).replaceAll("\\", "/");

export function k6CodeContext({ root, product, module, run, productDir, k6Project }) {
  const wp = workloadPaths(productDir, module);
  return {
    root, product, module, modules: run?.modules ?? [module], runId: run?.runId ?? null, productDir, k6Project, wp,
    codePlan: path.join(wp.dir, "code-plan.json"),
    parked: path.join(wp.dir, "parked.json"),
    legacy: path.join(wp.dir, "legacy"),
    k6Overlay: path.join(productDir, "foundation", "k6-overlay.json"),
    slotsRel: `scripts/slots/${module}.js`,
    slotsFile: path.join(k6Project, "scripts", "slots", `${module}.js`),
  };
}

// The managed and agent-writable paths (for permissions, S7-3), relative to the repo root.
export function k6CodePaths(ctx, model = null) {
  const k = (f) => rel(ctx.root, path.join(ctx.k6Project, f));
  return {
    agentWritable: { slots: k(ctx.slotsRel) },
    managed: {
      scripts: model ? model.scripts.map((s) => k(s.file)) : [],
      scriptsGlob: k(`scripts/${ctx.module}-*.js`),
      codePlan: rel(ctx.root, ctx.codePlan),
      parked: rel(ctx.root, ctx.parked),
      legacy: rel(ctx.root, ctx.legacy),
    },
    reads: { workload: rel(ctx.root, ctx.wp.workload), catalogue: rel(ctx.root, ctx.wp.catalogue), plan: rel(ctx.root, ctx.wp.plan), lib: k("lib") },
  };
}

// ---------- the model ----------

// The expected status of an endpoint's successful request: its happy-path plan scenario's expectation, else 2xx.
export function expectOf(plan, e) {
  const own = plan.filter((s) => s.endpoint === e.id && s.type === "functional" && !s.blocked && s.expect);
  const hit = own.find((s) => typeof s.expect.status === "number") ?? own.find((s) => Array.isArray(s.expect.statusIn) && s.expect.statusIn.length) ?? own[0];
  if (hit && typeof hit.expect.status === "number") return { status: hit.expect.status, source: `plan:${hit.id}` };
  if (hit && Array.isArray(hit.expect.statusIn) && hit.expect.statusIn.length) return { statusIn: hit.expect.statusIn.map(Number), source: `plan:${hit.id}` };
  return { statusClass: "2xx", source: hit ? `plan:${hit.id}` : "class-only" };
}

const methodOf = (e) => String(e.method ?? (e.kind === "graphql" ? "POST" : "GET")).toUpperCase();
const normBase = (p) => String(p ?? "").trim().replace(/\/+$/, "");

// The k6 overlay's basePath (artifacts/<p>/foundation/k6-overlay.json), which lib/config.js url() prepends; "" if none.
export const k6BasePath = (ctx) => normBase(readJson(ctx.k6Overlay, null)?.basePath?.path);

// What a request passes to url(): catalogue paths are full paths from the origin (endpoints.mjs joins a server's base
// path and the operation's path), and url() prepends the k6 overlay's basePath, so a path under that base path is
// emitted relative to it. A path the catalogue gives without a base path is emitted as it is. -> {urlPath} | {problem}
export function urlPathOf(e, basePath) {
  const p = String(e.path ?? "/");
  if (!basePath) return { urlPath: p };
  if (p === basePath || p.startsWith(`${basePath}/`)) return { urlPath: p.slice(basePath.length) || "/" };
  const own = normBase(e.basePath);
  if (own) return { problem: `${e.id} ${p} is under the base path ${own}, not the k6 overlay's basePath ${basePath} (lib/config.js url() prepends it): correct the k6 overlay (k6-lib-writer), or exclude the endpoint in the workload overlay` };
  return { urlPath: p };
}

// workload.json + catalogue + plan -> {problems, scripts[], slots[], mode, runId}. Pure.
export function computeModel(ctx) {
  const problems = [];
  const workload = readJson(ctx.wp.workload, null);
  if (!workload?.scenarios) return { problems: ["k6/workload.json is missing or not the script-built shape: run workload.mjs build, then check"] };
  const catalogue = readJson(ctx.wp.catalogue, []);
  const plan = readJson(ctx.wp.plan, []);
  const byId = new Map(catalogue.map((e) => [e.id, e]));
  const basePath = k6BasePath(ctx);
  const slots = new Map();
  const addSlot = (kind, endpoint, needed, id) => {
    const key = kind === "data" ? "data" : `${kind}:${endpoint}`;
    const s = slots.get(key) ?? { key, function: kind === "data" ? "setupData" : `${kind}_${safe(endpoint)}`, kind, ...(endpoint ? { endpoint } : {}), needed: false, usedBy: [] };
    s.needed ||= needed;
    if (id && !s.usedBy.includes(id)) s.usedBy.push(id);
    slots.set(key, s);
    return key;
  };
  addSlot("data", null, false);
  const scripts = [];
  for (const sc of workload.scenarios) {
    if (sc.data?.length) addSlot("data", null, true, sc.id);
    else addSlot("data", null, false, sc.id);
    const steps = sc.kind === "flow" ? sc.flow.steps : sc.endpoints.map((endpoint) => ({ endpoint }));
    // defence in depth (D-005): the flow rules again, on what workload.json says
    if (sc.kind === "flow") for (const p of flowProblems(sc.flow, byId)) problems.push(`${sc.id}: flow '${sc.flow.name}' ${p} (rebuild and check the workload)`);
    // a cleanup delete is a DELETE on a created entity's item path (isItemDeleteOf); only those get trackDeleted
    const entityDeletes = sc.kind === "flow" ? flowDeletes(sc.flow, byId) : new Map();
    if (sc.kind === "flow") {
      const root = rootDeleteStep(sc.flow, byId)?.endpoint ?? null;
      if ((sc.cleanup?.endpoint ?? null) !== root) problems.push(`${sc.id} [cleanup] workload.json names ${sc.cleanup?.endpoint ?? "no"} cleanup delete, but the flow's delete of its created entity (a DELETE on its item path) is ${root ?? "none"} (rebuild and check the workload)`);
    }
    const requests = [];
    const creates = [];
    for (const [i, st] of steps.entries()) {
      const e = byId.get(st.endpoint);
      if (!e) {
        problems.push(`${sc.id}: ${st.endpoint} is not in the endpoint catalogue (rebuild the workload)`);
        continue;
      }
      const method = methodOf(e);
      const params = pathParamsOf(e);
      const binds = sc.kind === "flow" ? bindsOf(st) : [];
      for (const b of binds) if (!params.includes(b.param)) problems.push(`${sc.id}: flow step ${i} binds '${b.param}', which is not a path parameter of ${e.id} ${e.path}`);
      const unbound = params.filter((p) => !binds.some((b) => b.param === p));
      const keys = [];
      // a mutating request's path parameters (a query-like one's too) come only from the flow's creates: never a path
      // slot (pre-existing data, D-005)
      if (unbound.length && e.mutates) problems.push(`${sc.id}: ${e.id} ${method} ${e.path} ${e.queryLike ? "is query-like but mutates" : "writes"}, and its path parameter${unbound.length > 1 ? "s" : ""} ${unbound.join(", ")} ${unbound.length > 1 ? "are" : "is"} bound to no create of a flow: a write never gets a path: slot (it would target pre-existing data, D-005)`);
      else if (unbound.length) keys.push(addSlot("path", e.id, true, sc.id));
      let deletes;
      if (sc.kind === "flow" && isCreate(e)) {
        const id = createIdPointer(catalogue, e);
        creates.push({ step: i, type: e.resource ?? sc.flow.name, pointer: id.pointer, assumed: !id.documented });
      } else if (entityDeletes.has(i)) deletes = entityDeletes.get(i);
      const query = (e.params ?? []).filter((p) => p.in === "query");
      if (query.length) keys.push(addSlot("query", e.id, query.some((p) => p.required), sc.id));
      if (BODY_METHODS.includes(method) || e.kind === "graphql") keys.push(addSlot("body", e.id, true, sc.id));
      keys.push(addSlot("checks", e.id, false, sc.id));
      const u = urlPathOf(e, basePath);
      if (u.problem) problems.push(`${sc.id}: ${u.problem}`);
      const urlPath = u.urlPath !== undefined && u.urlPath !== (e.path ?? "/") ? { urlPath: u.urlPath } : {};
      requests.push({ endpoint: e.id, method, path: e.path ?? "/", ...urlPath, pathParams: params, expect: expectOf(plan, e), slots: keys, ...(binds.length ? { bind: binds } : {}), ...(Number.isInteger(deletes) ? { deletes } : {}) });
    }
    // every create of a flow is tracked by its id pointer (step 0's is trackLeftover, the flow's root entity)
    const track = sc.kind === "flow" && creates[0]?.step === 0 ? (({ step, ...t }) => t)(creates[0]) : null;
    if (sc.kind === "flow" && !track) problems.push(`${sc.id}: flow '${sc.flow.name}' does not start with a create (rebuild and check the workload)`);
    scripts.push({
      id: sc.id, name: sc.name, file: `scripts/${ctx.module}-${sc.name}.js`, type: sc.type, kind: sc.kind, endpoints: sc.endpoints, mutates: !!sc.mutates,
      ...(sc.queryLike ? { queryLike: true } : {}),
      ...(sc.kind === "mix" ? { weights: sc.weights } : {}),
      requests,
      ...(track ? { trackLeftover: track, creates, cleanup: { endpoint: sc.cleanup?.endpoint ?? null } } : {}),
      thinkTimeMs: sc.thinkTimeMs ?? 0,
    });
  }
  const order = (s) => [SLOT_KINDS.indexOf(s.kind), s.endpoint ?? ""];
  const list = [...slots.values()].sort((a, b) => order(a)[0] - order(b)[0] || order(a)[1].localeCompare(order(b)[1], "en", { numeric: true }));
  return { problems, module: ctx.module, runId: workload.runId, mode: workload.mode, basePath, workload, scripts, slots: list };
}

// The code-plan.json of a model (filled: from the slot regions).
export function planOf(ctx, model, regions = new Map()) {
  return {
    module: ctx.module, runId: model.runId ?? null, mode: model.mode, basePath: model.basePath ?? "",
    files: { slots: ctx.slotsRel, scripts: model.scripts.map((s) => s.file) },
    scripts: model.scripts,
    slots: model.slots.map((s) => ({ ...s, filled: filled(regions.get(s.key)) })),
  };
}

// ---------- slot files ----------
const BEGIN = /^\s*\/\/ k6-code:begin (\S.*?)\s*$/;
const END = /^\s*\/\/ k6-code:end (\S.*?)\s*$/;

// -> {regions: Map key -> lines[], problems}
export function parseSlots(text) {
  const regions = new Map();
  const problems = [];
  let open = null;
  let body = [];
  nl(text).split("\n").forEach((l, i) => {
    const b = BEGIN.exec(l);
    const e = END.exec(l);
    if (b) {
      if (open) problems.push(`line ${i + 1}: slot '${b[1]}' starts inside slot '${open}'`);
      open = b[1];
      body = [];
    } else if (e) {
      if (!open) problems.push(`line ${i + 1}: 'k6-code:end ${e[1]}' without its begin`);
      else if (e[1] !== open) problems.push(`line ${i + 1}: slot '${open}' ends as '${e[1]}'`);
      else if (regions.has(open)) problems.push(`line ${i + 1}: slot '${open}' appears twice`);
      else regions.set(open, body);
      open = null;
    } else if (/^\s*\/\/\s*k6-code:/.test(l)) problems.push(`line ${i + 1}: a malformed slot marker (write it exactly "// k6-code:begin <key>" on its own line)`);
    else if (open) body.push(l);
  });
  if (open) problems.push(`slot '${open}' never ends`);
  return { regions, problems };
}

// Whether a slot holds code: a token outside comments that is not ";".
export const filled = (lines) => scanTs((lines ?? []).join("\n")).some((t) => t.type !== "comment" && t.value !== ";");

const slotLines = (key, body) => [`  // k6-code:begin ${key}`, ...(body ?? []), `  // k6-code:end ${key}`];

export function renderSlots(ctx, model, regions = new Map()) {
  const bySlot = new Map();
  for (const s of model.scripts) for (const r of s.requests) for (const k of r.slots) if (!bySlot.has(k)) bySlot.set(k, r);
  const needs = new Map();
  for (const s of model.workload.scenarios) for (const d of s.data ?? []) {
    const k = `${one(d.target)}: ${one(d.need)} (${one(d.citation)})`;
    needs.set(k, [...(needs.get(k) ?? []), s.id]);
  }
  const dataNeeds = [...needs].map(([k, ids]) => `${k} [${ids.join(", ")}]`);
  const L = [
    `// ${SLOT_HEADER}: write only between "// k6-code:begin <key>" and`,
    `// "// k6-code:end <key>". node scripts/k6-code.mjs build ${ctx.product} ${ctx.module} re-renders everything else and keeps every`,
    `// slot's body; a body whose slot is no longer generated is parked in artifacts/${ctx.product}/modules/${ctx.module}/k6/parked.json and comes`,
    "// back with its slot. The generated scripts (scripts/<module>-<name>.js) call these functions; they send every request.",
    "// Slot rules (k6-code.mjs check): plain values through the helpers imported here, the parameters and plain JavaScript",
    "// (Math, JSON, Date, String, Object.keys, ...). No request API, no import, require or open(), no __ENV, __VU or __ITER",
    "// (credentials and the environment stay in lib/), no sleep (think time is generated), no globalThis, eval or Function,",
    "// no URL or secret-shaped literal, no computed member access, no change to an object the slot did not create.",
    "import { checkJsonKeys, checkLatency, checkStatus } from '../../lib/checks.js';",
    "import { pick, uniqueEmail, uniqueName } from '../../lib/data.js';",
  ];
  for (const s of model.slots) {
    const r = bySlot.get(s.key);
    const ep = r ? `${s.endpoint} ${r.method} ${r.path}` : s.endpoint;
    const used = s.usedBy.length ? ` Used by ${s.usedBy.join(", ")}.` : "";
    const need = s.needed ? " Needed: a loaded scenario cannot run without it." : " Optional.";
    L.push("");
    if (s.kind === "data") {
      L.push(`// The setup data: setup() returns it, and every slot gets it as \`data\`. Return a plain object.${need}`);
      for (const d of dataNeeds) L.push(`//   - ${d}`);
      L.push("export function setupData() {");
    } else if (s.kind === "path") {
      L.push(`// ${ep}: return the path parameters { ${r.pathParams.filter((p) => !(r.bind ?? []).some((b) => b.param === p)).join(", ")} } (an entity that already exists: reads only).${need}${used}`);
      L.push(`export function ${s.function}(data, ref) {`);
    } else if (s.kind === "query") {
      L.push(`// ${ep}: return the query parameters as { name: value }.${need}${used}`);
      L.push(`export function ${s.function}(data, ref) {`);
    } else if (s.kind === "body") {
      L.push(`// ${ep}: return the JSON body (synthetic data: uniqueName, uniqueEmail; ref is the flow's created entity).${need}${used}`);
      L.push(`export function ${s.function}(data, ref) {`);
    } else {
      L.push(`// ${ep}: extra checks on res through checkStatus, checkJsonKeys and checkLatency (the status check is generated).${need}${used}`);
      L.push(`export function ${s.function}(res, data) {`);
    }
    L.push(...slotLines(s.key, regions.get(s.key)), "}");
  }
  return `${L.join("\n")}\n`;
}

// ---------- the scripts ----------
const statusExpr = (x) => (x.status !== undefined ? String(x.status) : x.statusIn ? `[${x.statusIn.join(", ")}]` : "STATUS_2XX");
const statusText = (x) => (x.status !== undefined ? String(x.status) : x.statusIn ? x.statusIn.join("|") : "2xx");
// The condition "res's status is not the expected one" (the plan's status, else any 2xx).
const statusMiss = (x, res) => (x.status !== undefined ? `${res}.status !== ${x.status}` : x.statusIn ? `![${x.statusIn.join(", ")}].includes(${res}.status)` : `${res}.status < 200 || ${res}.status >= 300`);

function pathExpr(r, pv, bound) {
  const p = r.urlPath ?? r.path;
  if (!r.pathParams.length) return q1(p);
  const esc = (s) => s.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
  return `\`${p.split(/(\{[^}]+\})/).map((part) => {
    const m = /^\{([^}]+)\}$/.exec(part);
    if (!m) return esc(part);
    return `\${encodeURIComponent(String(${bound.get(m[1]) ?? member(pv, m[1])}))}`;
  }).join("")}\``;
}

// The lines of one request: res = the response's variable; ref = what the slots get as ref; bound: param -> expr.
function requestLines(r, res, ref, bound, indent) {
  const fn = (kind) => (r.slots.includes(`${kind}:${r.endpoint}`) ? `${kind}_${safe(r.endpoint)}` : null);
  const out = [];
  const pv = `${res}Path`;
  if (fn("path")) out.push(`const ${pv} = ${fn("path")}(data, ${ref}) || {};`);
  let target = pathExpr(r, pv, bound);
  if (fn("query")) target = `withQuery(${target}, ${fn("query")}(data, ${ref}))`;
  const body = fn("body") ? `JSON.stringify(${fn("body")}(data, ${ref}))` : "null";
  const headers = fn("body") ? "headers: { 'Content-Type': 'application/json' }, " : "";
  out.push(`const ${res} = http.request(${q1(r.method)}, url(${target}), ${body}, params({ ${headers}tags: { endpoint: ${q1(r.endpoint)} } }));`);
  out.push(`checkStatus(${res}, ${statusExpr(r.expect)}, ${q1(`${r.endpoint} ${r.method} ${r.path} -> ${statusText(r.expect)}`)}); // expected status: ${r.expect.source}`);
  out.push(`${fn("checks")}(${res}, data);`);
  return out.map((l) => `${indent}${l}`);
}

export function renderScript(ctx, model, x) {
  const sc = model.workload.scenarios.find((s) => s.id === x.id);
  const fns = [...new Set(["setupData", ...x.requests.flatMap((r) => r.slots.map((k) => `${k.split(":")[0]}_${safe(k.slice(k.indexOf(":") + 1))}`))])];
  const needs2xx = x.requests.some((r) => r.expect.statusClass);
  const needsQuery = x.requests.some((r) => r.slots.some((k) => k.startsWith("query:")));
  const flow = x.kind === "flow";
  const think = x.thinkTimeMs > 0;
  const L = [
    `// ${HEADER}`,
    `// ${x.id} ${x.name}: type ${x.type}, kind ${x.kind}, ${x.mutates ? `mutates: requireFullRun(true), runs only in full-run` : "reads only: requireFullRun(false)"}.`,
    "// Endpoints:",
    ...x.requests.map((r) => `//   ${r.endpoint} ${r.method} ${r.path}`),
  ];
  if (x.kind === "mix") L.push(`// Why: a weighted mix (${Object.entries(x.weights).map(([k, v]) => `${k}=${v}`).join(", ")}), cited: ${one(sc.citation)}.`);
  else if (flow) L.push(`// Why: write flow '${one(sc.flow.name)}', cited: ${sc.flow.citations.map(one).join("; ")}.`);
  else L.push(`// Why: a single endpoint at the ${sc.load?.capSource ?? "default"} cap (average-load ${sc.load?.averageRps} rps, peak ${sc.load?.rps} rps)${x.queryLike ? "; a query-like POST: a read in load terms, still a write for the guard" : ""}.`);
  L.push(
    `// Load: ${sc.executor}, Little's law: ${sc.sizing?.preAllocatedVUs} pre-allocated VUs (max ${sc.sizing?.maxVUs}) for ${sc.sizing?.peakRps} rps x ${sc.sizing?.expectedIterationS} s x ${sc.sizing?.headroom}.`,
    `// Source: artifacts/${ctx.product}/modules/${ctx.module}/k6/workload.json. Rebuild: node scripts/k6-code.mjs build ${ctx.product} ${ctx.module}.`,
    `// The k6-script-writer's code is in ${ctx.slotsRel} (slots); this file is regenerated and never edited.`,
    "import http from 'k6/http';",
    ...(think ? ["import { sleep } from 'k6';"] : []),
    "import { assertAllowedHost, requireFullRun, url } from '../lib/config.js';",
    "import { params } from '../lib/auth.js';",
    "import { checkStatus } from '../lib/checks.js';",
    ...(flow ? [`import { ${x.requests.some((r) => r.deletes !== undefined) ? "trackDeleted, " : ""}trackLeftover, untrackedCreate } from '../lib/data.js';`] : []),
    `import { ${fns.join(", ")} } from './slots/${ctx.module}.js';`,
    "",
    "// From workload.json, verbatim.",
    `export const options = ${JSON.stringify(sc.options, null, 2)};`,
  );
  if (needs2xx) L.push("", "// The plan gives this endpoint's success only as a class: any 2xx.", "const STATUS_2XX = Array.from({ length: 100 }, (_, i) => 200 + i);");
  if (needsQuery)
    L.push(
      "",
      "// The query slot's { name: value } appended to the path, encoded.",
      "function withQuery(path, query) {",
      "  const q = query || {};",
      "  const parts = Object.keys(q).filter((k) => q[k] !== undefined && q[k] !== null).map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(String(q[k]))}`);",
      "  return parts.length ? `${path}?${parts.join('&')}` : path;",
      "}",
    );
  if (flow)
    L.push(
      "",
      "// The value at a JSON pointer of a response body (a flow's bind), or undefined.",
      "function at(res, pointer) {",
      "  let v;",
      "  try {",
      "    v = res.json();",
      "  } catch (e) {",
      "    return undefined;",
      "  }",
      "  for (const part of pointer.split('/').slice(1)) {",
      "    if (v === null || typeof v !== 'object') return undefined;",
      "    v = v[part.replace(/~1/g, '/').replace(/~0/g, '~')];",
      "  }",
      "  return v;",
      "}",
    );
  L.push("", "export function setup() {", "  assertAllowedHost();", `  requireFullRun(${x.mutates});`, "  return setupData() || {};", "}", "", "export default function (data) {");
  if (x.kind === "endpoint") L.push(...requestLines(x.requests[0], "res", "undefined", new Map(), "  "));
  else if (x.kind === "mix") {
    const total = x.requests.reduce((n, r) => n + x.weights[r.endpoint], 0);
    L.push(`  // weighted pick, weights from workload.json: ${x.requests.map((r) => `${r.endpoint} ${x.weights[r.endpoint]}/${total}`).join(", ")}`, `  const pick = Math.random() * ${total};`);
    let acc = 0;
    x.requests.forEach((r, i) => {
      acc += x.weights[r.endpoint];
      const head = i === 0 ? `  if (pick < ${acc}) {` : i === x.requests.length - 1 ? "  } else {" : `  } else if (pick < ${acc}) {`;
      L.push(head, ...requestLines(r, "res", "undefined", new Map(), "    "));
    });
    L.push("  }");
  } else {
    // every bind is a create's id (flowProblems): step 0's is `ref`, a child create's `ref<step>`
    const creates = new Map((x.creates ?? []).map((c) => [c.step, c]));
    const refOf = (step) => (step === 0 ? "ref" : `ref${step}`);
    x.requests.forEach((r, i) => {
      const bound = new Map((r.bind ?? []).map((b) => [b.param, refOf(b.from)]));
      const c = creates.get(i);
      const what = i === 0 ? "the create" : c ? "a child create under the created entity" : r.deletes === 0 ? "the delete: the cleanup of the entity this iteration created" : r.deletes !== undefined ? `the delete of step ${r.deletes + 1}'s child entity, before its parent` : "on the created entity only";
      L.push(`  // step ${i + 1} of ${x.requests.length}: ${r.endpoint} ${r.method} ${r.path} (${what})`);
      L.push(...requestLines(r, `r${i}`, i === 0 ? "undefined" : "ref", bound, "  "));
      if (r.deletes !== undefined && creates.has(r.deletes))
        L.push(`  if (r${i}.status >= 200 && r${i}.status < 300) trackDeleted(${q1(creates.get(r.deletes).type)}, ${refOf(r.deletes)}); // deleted: the summary drops it from the leftovers`);
      if (c) {
        const v = refOf(i);
        L.push(
          `  if (${statusMiss(r.expect, `r${i}`)}) return; // not the expected create status (${statusText(r.expect)}): nothing was created that this flow may touch, whatever the body names`,
          `  const ${v} = at(r${i}, ${q1(c.pointer)});${c.assumed ? " // no catalogue link documents the create's id: assumed at /id" : ""}`,
          `  if (${v} === undefined || ${v} === null || ${v} === '') {`,
          `    untrackedCreate(${q1(c.type)}, r${i}); // created, but its id is not at ${c.pointer}: logged as evidence, tracked by any id it carries, else reported as untracked`,
          "    return;",
          "  }",
          `  trackLeftover(${q1(c.type)}, ${v}); // recorded at once, so the ledger lists every entity this run created (D-005)`,
        );
      }
    });
    if (!x.cleanup.endpoint) L.push("  // no delete step: the API offers none in this flow; the entity stays recorded by trackLeftover for the ledger");
  }
  if (think) L.push(`  // think time ${x.thinkTimeMs} ms, from workload.json, cited: ${one(sc.thinkTimeCitation ?? "workload.json")}`, `  sleep(${x.thinkTimeMs / 1000});`);
  else L.push("  // no think time: the arrival rate alone paces the iterations (open model)");
  L.push("}", "");
  if (x.mutates && !x.queryLike)
    L.push(
      "// teardown(): setup() creates nothing (the slots return plain values and send no request), so there is nothing to",
      "// delete here. k6 VUs share no iteration state: each iteration deletes the entity it created in its last step, and",
      "// trackLeftover records it right after the create, so the runner-triager puts it in the run's ledger (D-005).",
    );
  else L.push("// teardown(): this scenario creates nothing, so there is nothing to clean up.");
  L.push("export function teardown() {}", "", "export { handleSummary } from '../lib/summary.js';", "");
  return L.join("\n");
}

// ---------- the script rules (check, criterion 5) ----------
const codeTokens = (text) => scanTs(nl(text)).filter((t) => t.type !== "comment");

// The `export const options = {...};` literal of a script. -> object | null
export function parseOptions(text) {
  const m = /^export const options = (\{[\s\S]*?\n\});$/m.exec(nl(text));
  if (!m) return null;
  try {
    return JSON.parse(m[1]);
  } catch {
    return null;
  }
}
const setupBody = (text) => /^export function setup\(\) \{\n([\s\S]*?)\n\}$/m.exec(nl(text))?.[1] ?? null;

// The rules on one script's text: x (code-plan script), sc (workload scenario), workload. -> problems[]
export function scriptRules(file, text, sc, workload, x = null) {
  const out = [];
  const p = (rule, msg) => out.push(`${file} [${rule}] ${msg}`);
  const t = nl(text);
  const opts = parseOptions(t);
  if (!opts) p("options", "has no `export const options = {...};` JSON literal: options come from workload.json verbatim");
  else {
    if (!same(opts.scenarios, sc.options.scenarios)) p("options", `options.scenarios differ from workload.json ${sc.id}`);
    if (!same(opts.thresholds, sc.options.thresholds)) p("thresholds", `options.thresholds differ from workload.json ${sc.id}`);
    for (const k of Object.keys(opts)) if (!["scenarios", "thresholds"].includes(k)) p("options", `options.${k} is not in workload.json`);
    if (!(opts.thresholds?.dropped_iterations ?? []).length) p("dropped-iterations", "no dropped_iterations threshold: an under-delivering generator would pass");
  }
  const setup = setupBody(t);
  const calls = [...(setup ?? "").matchAll(/\brequireFullRun\(\s*(true|false)\s*\)/g)].map((m) => m[1] === "true");
  if (!setup || !/\bassertAllowedHost\(\)/.test(setup)) p("allowed-host", "setup() does not call assertAllowedHost()");
  if (!calls.length) p("full-run", "setup() does not call requireFullRun(<mutates>)");
  else if (calls.some((c) => c !== !!sc.mutates)) p("full-run", `requireFullRun(${calls.join(", ")}) but ${sc.id} has mutates: ${!!sc.mutates}`);
  if (workload.mode !== "full-run" && sc.mutates) p("readonly-write", `${sc.id} is a write scenario in a readonly workload`);
  const toks = codeTokens(t);
  const called = (name) => toks.some((x, i) => x.type === "ident" && x.value === name && toks[i + 1]?.value === "(" && toks[i - 1]?.value !== "function");
  if (sc.mutates && !sc.queryLike && !called("trackLeftover")) p("cleanup", "a write without trackLeftover: every entity the run creates goes to the ledger");
  if (sc.cleanup?.endpoint && !t.includes(`tags: { endpoint: '${sc.cleanup.endpoint}' }`)) p("cleanup", `the flow's delete step ${sc.cleanup.endpoint} is not requested`);
  if (sc.cleanup?.endpoint && !called("trackDeleted")) p("cleanup", `no trackDeleted after the flow's delete step ${sc.cleanup.endpoint}: a deleted entity would stay listed as a leftover`);
  if (x) {
    // trackDeleted only after a DELETE on a created entity's item path: any other DELETE leaves the entity a leftover
    const want = x.requests.filter((r) => r.deletes !== undefined).length;
    const got = toks.filter((y, i) => y.type === "ident" && y.value === "trackDeleted" && toks[i + 1]?.value === "(" && toks[i - 1]?.value !== "function" && toks[i - 1]?.value !== "{" && toks[i - 1]?.value !== ",").length;
    if (got !== want) p("cleanup", `${got} trackDeleted call${got === 1 ? "" : "s"}, but ${want} step${want === 1 ? "" : "s"} delete${want === 1 ? "s" : ""} a created entity on its item path: only such a delete drops an entity from the leftovers (D-005)`);
    if (sc.cleanup?.endpoint && !x.requests.some((r) => r.endpoint === sc.cleanup.endpoint && r.deletes === 0)) p("cleanup", `${sc.cleanup.endpoint} is not a DELETE on the created entity's item path: not a cleanup`);
  }
  for (const x of toks) {
    const v = x.type === "tpl" ? x.cooked : x.type === "str" ? x.value : null;
    if (v !== null && URL_RE.test(v)) p("hard-coded-url", `a hard-coded URL (${String(v).slice(0, 40)}): the target is BASE_URL, through url() from lib/config.js`);
    if (x.type === "ident" && (x.value === "BASE_URL" || x.value === "__ENV")) p("base-url", `uses ${x.value}: BASE_URL and the environment are lib/config.js's (no default)`);
  }
  const lines = t.split("\n");
  lines.forEach((l, i) => {
    if (/\bsleep\(/.test(l.replace(/\/\/.*$/, "")) && !/\/\/\s*\S/.test(l) && !/^\s*\/\/\s*\S/.test(lines[i - 1] ?? "")) p("sleep-comment", `line ${i + 1}: sleep() without a think-time comment`);
  });
  toks.forEach((x, i) => {
    if (!(x.value === "request" && toks[i - 1]?.value === "." && toks[i - 2]?.value === "http")) return;
    const close = toks.findIndex((y, j) => j > i && y.value === ";");
    const call = toks.slice(i, close < 0 ? undefined : close);
    if (!call.some((y, j) => y.value === "tags" && call[j + 2]?.value === "{" && call[j + 3]?.value === "endpoint")) p("endpoint-tag", `line ${x.line}: a request without the endpoint tag (the thresholds are per endpoint)`);
  });
  if (!/^export \{ handleSummary \} from '\.\.\/lib\/summary\.js';$/m.test(t)) p("summary", "does not export handleSummary from '../lib/summary.js'");
  return out;
}

// ---------- slot scan ----------
// The k6 rules on one slot body. -> problems[]
export function slotFindings(file, key, lines, startLine) {
  const kind = key === "data" ? "data" : key.split(":")[0];
  const code = lines.join("\n");
  const out = [];
  const at = (line) => startLine + (line ?? 1);
  const fmt = (f) => `${f.file}:${f.line ?? startLine} [${f.rule}] ${key}: ${f.problem}`;
  const declared = [...SLOT_PARAMS[kind], ...(kind === "checks" ? SLOT_HELPERS.checks : SLOT_HELPERS.value)];
  out.push(...freeIdentifierFindings(file, code, { declared, wrap: true, at }).map(fmt));
  const pickHint = (f) => (f.rule === "computed-access" && kind !== "checks" ? { ...f, problem: `${f.problem}; for a random element of an array use pick(array) from lib/data.js` } : f);
  out.push(...propertyFindings(file, code, { wrap: true, at: (t) => at(t?.line), kind: "slot" }).map(pickHint).map(fmt));
  out.push(...builtinPatchFindings(file, code, (t) => at(t?.line), { wrap: true }).map(fmt));
  const push = (t, rule, msg) => out.push(`${file}:${at(t.loc?.start?.line ?? t.line)} [${rule}] ${key}: ${msg}`);
  // the body stays inside its function: it parses on its own as a function body, so no bracket closes what the skeleton
  // opened and none stays open, and it holds no import or export
  const tree = parseAgentCode(code, { wrap: true });
  if (!tree) {
    out.push(`${file}:${startLine} [slot-structure] ${key}: closes a bracket the slot did not open or leaves one open (it does not parse on its own as a function body): a slot body stays inside its function`);
    return out;
  }
  const strs = [];
  let returns = false;
  astWalk(tree.ast, (n, parent, k) => {
    if (/^(Import|Export)/.test(n.type)) push(n, "slot-forbidden", `uses ${n.type.startsWith("Import") ? "import" : "export"}: a slot returns plain values; requests, the environment, imports, sleep and the runtime are the generated script's and the lib's`);
    if (n.type === "ImportExpression") push(n, "slot-forbidden", "uses import: a slot returns plain values; requests, the environment, imports, sleep and the runtime are the generated script's and the lib's");
    if (n.type === "Identifier") {
      const member = parent?.type === "MemberExpression" && k === "property" && !parent.computed;
      const key2 = (parent?.type === "Property" || parent?.type === "MethodDefinition" || parent?.type === "PropertyDefinition") && k === "key" && !parent.computed && !parent.shorthand;
      if (member && BAD_MEMBERS.includes(n.name)) push(n, "call-apply-bind", `uses .${n.name}: call functions directly, by name`);
      else if (!member && !key2 && SLOT_FORBIDDEN.includes(n.name)) push(n, "slot-forbidden", `uses ${n.name}: a slot returns plain values; requests, the environment, imports, sleep and the runtime are the generated script's and the lib's`);
    }
    const v = n.type === "Literal" && typeof n.value === "string" && !/^Import|^Export/.test(parent?.type ?? "") ? n.value : n.type === "TemplateLiteral" ? n.quasis.map((q) => q.value.cooked ?? "").join("") : null;
    if (v !== null) {
      strs.push(v);
      if (URL_RE.test(v) || v.includes("://")) push(n, "hard-coded-url", "a URL literal: the target is BASE_URL, and only the generated script builds a URL");
      if (looksLikeSecret(v)) push(n, "secret", "a secret-shaped literal: credentials come only from the environment, through lib/auth.js");
    }
  });
  // a return of the slot body itself, not of a function inside it
  const topReturn = (n) => {
    if (n.type === "ReturnStatement") returns = true;
    if (/Function/.test(n.type)) return;
    for (const c of Object.values(n)) for (const x of Array.isArray(c) ? c : [c]) if (x && typeof x.type === "string") topReturn(x);
  };
  topReturn(tree.ast);
  if (URL_RE.test(strs.join(""))) out.push(`${file}:${startLine} [hard-coded-url] ${key}: string pieces that join into a URL`);
  if (kind !== "checks" && filled(lines) && !returns) out.push(`${file}:${startLine} [slot-return] ${key}: returns nothing: return the plain value`);
  return out;
}

// ---------- build ----------
export const HEADER_RE = /^\/\/ Generated by scripts\/k6-code\.mjs — do not edit\.\n\/\/ (K6-[\w-]+-\d+) /;
// The files under scripts/ named "<m>-*.js" that belong to this module (not to a longer module name of the run).
function ownedScripts(ctx) {
  const longer = ctx.modules.filter((m) => m !== ctx.module && m.startsWith(`${ctx.module}-`));
  return walk(ctx.k6Project, "scripts", /\.js$/).filter((f) => {
    const base = path.posix.basename(f);
    return path.posix.dirname(f) === "scripts" && base.startsWith(`${ctx.module}-`) && !longer.some((m) => base.startsWith(`${m}-`));
  });
}
const readText = (f) => (existsSync(f) ? nl(readFileSync(f, "utf8")) : null);
function writeIfChanged(file, text) {
  if (readText(file) === text) return false;
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, text);
  return true;
}

const workloadGate = (ctx) => {
  const why = workloadUnverified(ctx.wp, ctx.runId);
  return why ? `the workload is not verified (${why}): run node scripts/workload.mjs build ${ctx.product} ${ctx.module}, then node scripts/workload.mjs check ${ctx.product} ${ctx.module}` : null;
};

export async function build(ctx, validate, { adopt = false } = {}) {
  const gate = workloadGate(ctx);
  if (gate) return { code: 1, out: { problems: [gate], next: "verify the workload first; nothing was written" } };
  const model = computeModel(ctx);
  if (model.problems.length) return { code: 1, out: { problems: model.problems, next: "fix the workload; nothing was written" } };
  const problems = [];
  const written = [];
  const removed = [];
  const adopted = [];
  const newlyParked = [];
  const restored = [];
  // the slot file: the skeleton around the agent's bodies; a body whose slot is gone is parked, and comes back
  const old = readText(ctx.slotsFile);
  const parsed = parseSlots(old ?? "");
  if (old !== null && !old.startsWith(`// ${SLOT_HEADER}`)) problems.push(`${ctx.slotsRel} has no generator header: move it away (its code goes into the slots), then build again`);
  if (parsed.problems.length) problems.push(...parsed.problems.map((p) => `${ctx.slotsRel}: ${p} -- fix the markers by hand; nothing was rewritten`));
  if (problems.length) return { code: 1, out: { problems, next: "fix the slot file; nothing was written" } };
  const parked = readJson(ctx.parked, { module: ctx.module, regions: {} });
  const want = new Set(model.slots.map((s) => s.key));
  const regions = new Map();
  for (const key of want) {
    if (parsed.regions.has(key)) regions.set(key, parsed.regions.get(key));
    else if (parked.regions[key]) {
      regions.set(key, parked.regions[key].lines);
      restored.push(key);
      delete parked.regions[key];
    }
  }
  for (const [key, lines] of parsed.regions)
    if (!want.has(key) && filled(lines)) {
      parked.regions[key] = { lines, run: ctx.runId };
      newlyParked.push(key);
    }
  if (newlyParked.length || restored.length || existsSync(ctx.parked)) {
    const pb = await validate("k6-code-parked", parked);
    if (pb.length) return { code: 1, out: { problems: pb.map((e) => `parked.json (internal): ${e}`) } };
    writeJson(ctx.parked, parked);
  }
  if (writeIfChanged(ctx.slotsFile, renderSlots(ctx, model, regions))) written.push(ctx.slotsRel);
  // the scripts: one per scenario; a generated script of this module no scenario names any more is removed
  const files = new Set(model.scripts.map((s) => s.file));
  for (const f of ownedScripts(ctx)) {
    if (files.has(f)) continue;
    const text = readText(path.join(ctx.k6Project, f));
    if (text.startsWith(`// ${HEADER}`)) {
      unlinkSync(path.join(ctx.k6Project, f));
      removed.push(f);
    } else if (adopt) {
      mkdirSync(ctx.legacy, { recursive: true });
      renameSync(path.join(ctx.k6Project, f), path.join(ctx.legacy, path.posix.basename(f)));
      adopted.push(f);
    }
  }
  for (const x of model.scripts) if (writeIfChanged(path.join(ctx.k6Project, x.file), renderScript(ctx, model, x))) written.push(x.file);
  const plan = planOf(ctx, model, regions);
  const pp = await validate("k6-code-plan", plan);
  if (pp.length) return { code: 1, out: { problems: pp.map((e) => `code-plan.json (internal): ${e}`) } };
  writeJson(ctx.codePlan, plan); // unstamped: it must pass check
  const empty = plan.slots.filter((s) => s.needed && !s.filled).map((s) => s.key);
  return {
    code: 0,
    out: {
      scripts: plan.scripts.map((s) => `${s.file} (${s.id})`), slots: ctx.slotsRel, needed: plan.slots.filter((s) => s.needed).length, emptyNeeded: empty,
      written, removed, ...(adopt ? { adopted } : {}), parkedSlots: newlyParked, restoredSlots: restored, problems: [],
      next: empty.length ? `fill the needed slots in ${ctx.slotsRel} (${empty.join(", ")}), then run k6-code.mjs check` : "run k6-code.mjs check",
    },
  };
}

// ---------- check ----------
const verifiedInputs = (ctx, plan) => ({
  workload: ctx.wp.workload, workloadCoverage: ctx.wp.coverage, catalogue: ctx.wp.catalogue, plan: ctx.wp.plan, k6Overlay: ctx.k6Overlay, slots: ctx.slotsFile,
  ...Object.fromEntries((plan?.scripts ?? []).map((s) => [`script:${s.file}`, path.join(ctx.k6Project, s.file)])),
});

// k6 inspect, offline, only when k6 is on PATH and never under node --test. -> (file, cwd) -> {out} | {error}, or a
// string saying why it is skipped.
export function defaultInspect() {
  if (process.env.NODE_TEST_CONTEXT) return "skipped: under node --test";
  try {
    execFileSync("k6", ["version"], { stdio: "ignore", shell: process.platform === "win32", timeout: 30_000 });
  } catch {
    return "skipped: k6 is not on PATH";
  }
  return (file, cwd) => {
    try {
      return { out: execFileSync("k6", ["inspect", file], { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], shell: process.platform === "win32", timeout: 120_000 }) };
    } catch (e) {
      return { error: `${e.stdout ?? ""}${e.stderr ?? ""}`.trim().split(/\r?\n/).slice(0, 6).join(" / ") || e.message };
    }
  };
}

// -> {problems, slots, inspect}
export async function check(ctx, validate, { inspect = defaultInspect() } = {}) {
  const gate = workloadGate(ctx);
  if (gate) return { problems: [gate], inspect: "not run" };
  const problems = [];
  const model = computeModel(ctx);
  problems.push(...model.problems);
  if (!model.scripts) return { problems, inspect: "not run" };
  const plan = readJson(ctx.codePlan, null);
  if (!plan) problems.push(`code-plan.json is missing: run node scripts/k6-code.mjs build ${ctx.product} ${ctx.module}`);
  else for (const e of await validate("k6-code-plan", plan)) problems.push(`code-plan.json: ${e}`);
  // the slot file: markers, the skeleton, the scan, every needed slot filled
  const text = readText(ctx.slotsFile);
  let regions = new Map();
  if (text === null) problems.push(`${ctx.slotsRel} is missing: run k6-code.mjs build`);
  else {
    const parsed = parseSlots(text);
    if (parsed.problems.length) problems.push(...parsed.problems.map((p) => `${ctx.slotsRel} [slot-markers] ${p}: restore the markers exactly as generated`));
    else {
      regions = parsed.regions;
      const want = new Set(model.slots.map((s) => s.key));
      for (const k of regions.keys()) if (!want.has(k)) problems.push(`${ctx.slotsRel} [slot-unknown] slot '${k}' is not generated: run k6-code.mjs build (it parks the body)`);
      if (renderSlots(ctx, model, regions) !== text) problems.push(`${ctx.slotsRel} [skeleton] generated code outside the slots was changed: run k6-code.mjs build to restore it; write only inside the slots`);
      const lines = text.split("\n");
      for (const [key, body] of regions) {
        if (!want.has(key)) continue;
        const start = lines.findIndex((l) => BEGIN.exec(l)?.[1] === key) + 1;
        problems.push(...slotFindings(ctx.slotsRel, key, body, start));
      }
      for (const s of model.slots) if (s.needed && !filled(regions.get(s.key))) problems.push(`${ctx.slotsRel} [empty-slot] ${s.key} is empty, and ${s.usedBy.join(", ") || "a loaded scenario"} need${s.usedBy.length > 1 ? "" : "s"} it`);
    }
  }
  const fresh = planOf(ctx, model, regions);
  const strip = ({ verified, ...p }) => ({ ...p, slots: p.slots?.map(({ filled: _, ...s }) => s) });
  const planOk = !!plan && same(strip(plan), strip(fresh));
  if (plan && !planOk) problems.push(`code-plan.json differs from a fresh build (the workload or the plan changed, or a hand edit): run k6-code.mjs build`);
  // the scripts: one per id, nothing extra, no drift, the rules
  const owned = ownedScripts(ctx);
  const byId = new Map();
  for (const f of owned) {
    const t = readText(path.join(ctx.k6Project, f));
    const head = HEADER_RE.exec(t)?.[1];
    const ids = head ? [head] : [...new Set(t.match(new RegExp(`K6-${ctx.module}-\\d+(?!\\d)`, "g")) ?? [])];
    for (const id of ids) byId.set(id, [...(byId.get(id) ?? []), f]);
    if (!ids.some((id) => model.scripts.some((x) => x.id === id))) problems.push(`${f} [extra-script] names no scenario of workload.json${ids.length ? ` (${ids.join(", ")})` : ""}: run k6-code.mjs build (it removes generated orphans; --adopt moves hand-written files to k6/legacy/)`);
  }
  for (const x of model.scripts) {
    const files = byId.get(x.id) ?? [];
    const abs = path.join(ctx.k6Project, x.file);
    if (!existsSync(abs)) problems.push(`${x.file} [missing-script] ${x.id} has no script: run k6-code.mjs build`);
    if (files.length > 1) problems.push(`${files.join(", ")} [duplicate-script] ${x.id} is implemented by ${files.length} scripts: one script per scenario`);
    if (!existsSync(abs)) continue;
    const t = readText(abs);
    if (t !== renderScript(ctx, model, x)) problems.push(`${x.file} [drift] differs from a fresh render: scripts are generated, never edited; change the slots or the workload and run k6-code.mjs build`);
    problems.push(...scriptRules(x.file, t, model.workload.scenarios.find((s) => s.id === x.id), model.workload, x));
  }
  // k6 inspect (offline): every script loads, and its options are the workload's
  let inspected = typeof inspect === "string" ? inspect : "ran";
  if (typeof inspect === "function")
    for (const x of model.scripts) {
      if (!existsSync(path.join(ctx.k6Project, x.file))) continue;
      const r = inspect(x.file, ctx.k6Project);
      if (r.error) {
        problems.push(`${x.file} [inspect] k6 inspect failed: ${r.error}`);
        continue;
      }
      let o = null;
      try {
        o = JSON.parse(r.out);
      } catch {}
      const sc = model.workload.scenarios.find((s) => s.id === x.id);
      const ex = o?.scenarios?.[sc.name]?.executor;
      if (o && ex !== sc.options.scenarios[sc.name].executor) problems.push(`${x.file} [inspect] k6 inspect reports scenario ${sc.name} with executor ${ex}, workload.json has ${sc.options.scenarios[sc.name].executor}`);
      if (o?.thresholds && !same(Object.keys(o.thresholds).sort(), Object.keys(sc.options.thresholds).sort())) problems.push(`${x.file} [inspect] k6 inspect reports thresholds on ${Object.keys(o.thresholds).join(", ")}, not workload.json's`);
    }
  const valid = !problems.length;
  // the plan records which slots are filled; a pass stamps it, a failure clears the stamp
  if (planOk) writeJson(ctx.codePlan, { ...fresh, ...(valid ? { verified: stampVerified(verifiedInputs(ctx, fresh)) } : {}) });
  const slots = { needed: fresh.slots.filter((s) => s.needed).length, filled: fresh.slots.filter((s) => s.filled).map((s) => s.key), emptyNeeded: fresh.slots.filter((s) => s.needed && !s.filled).map((s) => s.key) };
  return { problems, slots, inspect: inspected };
}

// For the domain flow (S7-3): null when the scripts passed k6-code.mjs check and nothing they rest on changed since.
export function k6CodeUnverified(ctx) {
  const w = workloadUnverified(ctx.wp, ctx.runId);
  if (w) return `the workload is not verified: ${w}`;
  const plan = readJson(ctx.codePlan, null);
  if (!plan) return "k6/code-plan.json is missing: the script-writer must finish with k6-code.mjs check";
  return unverifiedReason(plan.verified, verifiedInputs(ctx, plan), { unstamped: "the k6 scripts did not pass k6-code.mjs check", changed: "the scripts, the slots or the workload changed after k6-code.mjs check" });
}
